 pub fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{if !self.closing{return Err(invalid())}if self.terminal_is_empty(){return Ok(0)}if self.receiver.reserved()||self.retired_header.is_some(){return native_receiver_backing_work::<I,T,F::Receiver>(&self.receiver,&self.retired_header,body)}self.retirement.next_owner_work::<T>(self.output.is_some(),&None,body)}
